// "Delete the folder and it's gone" as a check: the app keeps everything it
// persists under `~/Library/Application Support/LaughCounter/`, so the only
// system directory its sources may ask macOS for is the Application Support
// one. Scans `mac/Sources/` for the APIs that *select* a search-path directory
// and requires the literal `.applicationSupportDirectory`.
//
// A whitelist, not a blacklist. Earlier sweeps left this rule as prose because
// proving "nothing lands outside the directory" looked like it needed data-flow
// tracking of every write target back to its declaration. It doesn't: every
// persistent path in the app is rooted at a `FileManager` search-path lookup,
// and there are exactly two of them (`AppLog.swift`, `Store.swift`), both
// `.applicationSupportDirectory`. Constraining the *root* constrains every path
// derived from it, and matching the allowed constant positively means a
// `SearchPathDirectory` case that doesn't exist yet is caught the day it lands —
// which an enumerate-the-bad-ones list would miss.
//
// Two deliberate consequences, both wanted:
//   - A non-literal argument (`urls(for: dir, in:)`) is a finding. Indirection
//     is exactly what would defeat the check, and no caller needs it here.
//   - The Login Item registration RULES.md carves out doesn't go through these
//     APIs at all (`SMAppService` names no directory), so it needs no exemption.
//
// Dependency-free by design (a local pack must load without the canon mount),
// so the finding object is built by hand rather than via the engine helper.

const ALLOWED = 'applicationSupportDirectory';

// The APIs that pick a system directory. `\s*` spans newlines, so a call split
// across lines (`urls(\n    for: .cachesDirectory,`) is matched too.
const SELECTORS = [
  // FileManager.default.urls(for:in:) and .url(for:in:appropriateFor:create:)
  [/\burls?\s*\(\s*for\s*:\s*([^,\s)]+)/g, 'FileManager.urls(for:)'],
  [/\bNSSearchPathForDirectoriesInDomains\s*\(\s*([^,\s)]+)/g, 'NSSearchPathForDirectoriesInDomains'],
];

const inScope = (f) => f.startsWith('mac/Sources/') && f.endsWith('.swift');

// `.applicationSupportDirectory`, `FileManager.SearchPathDirectory.applicationSupportDirectory`
// and a bare `applicationSupportDirectory` all name the same case.
const caseName = (token) => token.replace(/^.*\./, '');

const rule = {
  id: 'on-device-privacy/single-storage-directory',
  severity: 'blocking',
  description: 'The app asks macOS for only one directory: .applicationSupportDirectory (mac/Sources/)',
  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
  why: '"delete the folder and it\'s gone" is a promise a user acts on — a second storage root means the mic\'s memory of them outlives the directory they deleted',

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter(inScope)) {
      const text = ctx.read(file);
      if (text === null) continue;
      for (const [pattern, what] of SELECTORS) {
        pattern.lastIndex = 0;
        let m = pattern.exec(text);
        while (m !== null) {
          const token = m[1];
          if (caseName(token) !== ALLOWED) {
            out.push({
              rule: rule.id,
              severity: rule.severity,
              file,
              line: text.slice(0, m.index).split('\n').length,
              what: `${what} asks for \`${token}\`, not \`.${ALLOWED}\` (${file})`,
              why: rule.why,
              fix: `root the path at \`FileManager.default.urls(for: .${ALLOWED}, in: .userDomainMask)[0]\` and hang it off the app's existing \`LaughCounter\` directory; a second storage root is a product decision that belongs in RULES.md first`,
              doc: rule.doc,
            });
          }
          m = pattern.exec(text);
        }
      }
    }
    return out;
  },
};

export default rule;
===== no-listener =====
// "There is no server either" as a check: the app accepts no inbound
// connection. Scans the app's sources (`mac/Sources/`) for the APIs that open a
// *listening* socket, and for the server frameworks a dashboard would arrive on.
//
// The rule has history. A web dashboard did once exist, in the Python reference,
// and it was removed on purpose along with the reference itself — a listener is
// a decision about who may read the laugh log, and the log is the room's memory.
// That is why reintroducing one is gated on the owner's sign-off, a loopback-only
// default and an auth/CSRF story (the finding's `fix` says so), rather than being
// a feature someone adds on the way past.
//
// Its sibling `no-network-client` covers the outbound half, and earlier sweeps
// read that as covering this half too — a Network-framework `NWListener` needs
// `import Network`, which that check already bans. True, but not the whole
// surface: a listener does not have to come through the Network framework.
// `socket(2)` is reachable from plain `import Foundation` (Darwin is re-exported),
// `NSXPCListener`, `CFSocket*` and `NSSocketPort` are Foundation types, and an
// embedded HTTP server (Vapor, SwiftNIO, Swifter, GCDWebServer) arrives as an
// import, not as `import Network`. None of those trip `no-network-client`. This
// check closes that gap.
//
// Deliberately NOT banned: a bare `listen(`. This is an app whose whole domain
// vocabulary is listening — `requestListening()`, `finishListening()`, `private
// var listening` — and a mic-listening method named `listen()` is a false alarm
// waiting to happen. It costs nothing to drop: BSD sockets are created before
// they are listened on, so `socket(` catches the same code one line earlier, and
// "socket" carries no microphone meaning here. A fixture pins the vocabulary.
//
// Dependency-free by design (a local pack must load without the canon mount),
// so the finding object is built by hand rather than via the engine helper.

const LISTENERS = [
  [/\bNWListener\b/, 'NWListener (a Network-framework listener)'],
  [/\bNSXPCListener\b/, 'NSXPCListener'],
  [/\bCFSocket[A-Za-z]*\s*\(/, 'a CFSocket API'],
  [/\b(?:NS)?SocketPort\b/, 'SocketPort'],
  // The BSD socket primitive. Creating one precedes both listen(2) and
  // connect(2), so this catches a hand-rolled server (and a hand-rolled client).
  [/\bsocket\s*\(/, 'socket(2)'],
  // An embedded HTTP server, which arrives as a package import rather than as
  // anything in the Network framework.
  [
    /^\s*import\s+(?:Vapor|NIO[A-Za-z]*|Swifter|Telegraph|Hummingbird|Kitura[A-Za-z]*|Perfect[A-Za-z]*|FlyingFox|Embassy|GCDWebServer|Criollo)\b/,
    'an embedded HTTP server framework',
  ],
];

const inScope = (f) => f.startsWith('mac/Sources/') && f.endsWith('.swift');

const rule = {
  id: 'on-device-privacy/no-listener',
  severity: 'blocking',
  description: 'No inbound listener — no socket, XPC listener or embedded HTTP server (mac/Sources/)',
  doc: '.claudinite/local/packs/on-device-privacy/RULES.md',
  why: 'a listener exposes the laugh log to whatever can reach the port — reintroducing one is a decision about who may read the room, not a feature',

  run(ctx) {
    const out = [];
    for (const file of ctx.files.filter(inScope)) {
      const text = ctx.read(file);
      if (text === null) continue;
      const lines = text.split('\n');
      for (let i = 0; i < lines.length; i += 1) {
        for (const [pattern, what] of LISTENERS) {
          if (!pattern.test(lines[i])) continue;
          out.push({
            rule: rule.id,
            severity: rule.severity,
            file,
            line: i + 1,
            what: `${what} in the app (${file})`,
            why: rule.why,
            fix: "drop the listener; a dashboard, metrics port or remote-control API needs the owner's explicit sign-off, a loopback-only default and an auth/CSRF story written into RULES.md before any of it is written in Swift",
            doc: rule.doc,
          });
          break;
        }
      }
    }
    return out;
  },
};

export default rule;

// Red-first fixtures for the on-device-privacy checks: each rule must fire on a
// violating file and stay quiet on the repo's real, clean one. Run directly:
//
//   node --test .claudinite/local/packs/on-device-privacy/pack.test.mjs
//
// They live here rather than in tests/ (`claudinite-isolation`). The fake ctx is
// the slice of the engine's context a check actually uses — `files` and `read` —
// so these tests need neither the canon mount nor a git checkout.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import noNetworkClient from './no-network-client.mjs';
import onDeviceSpeech from './on-device-speech.mjs';
import noAudioPersistence from './no-audio-persistence.mjs';
import singleStorageDirectory from './single-storage-directory.mjs';
import noListener from './no-listener.mjs';

const repoRoot = dirname(dirname(dirname(dirname(dirname(fileURLToPath(import.meta.url))))));

// Fixture ctx: an in-memory tree of { path: contents }.
const ctxOf = (tree) => ({
  files: Object.keys(tree),
  read: (path) => tree[path] ?? null,
});

// The real tree, so a rule that starts firing on the actual sources fails here.
const realCtx = (...paths) => ctxOf(Object.fromEntries(
  paths.map((p) => [p, readFileSync(join(repoRoot, p), 'utf8')])
));

test('no-network-client fires on a client in the capture path', () => {
  const findings = noNetworkClient.run(ctxOf({
    'mac/Sources/LaughCounter/Sync.swift': 'let task = URLSession.shared.dataTask(with: url)\n',
    'mac/Sources/LaughCounter/Peer.swift': 'import Foundation\nimport Network\n',
  }));
  assert.equal(findings.length, 2);
  assert.deepEqual(findings.map((f) => f.line), [1, 2]);
  assert.match(findings[0].what, /URLSession/);
  assert.match(findings[1].what, /Network framework/);
});

test('no-network-client stays quiet on the real capture path', () => {
  const findings = noNetworkClient.run(realCtx(
    'mac/Sources/LaughCounter/AudioHub.swift',
    'mac/Sources/LaughCounter/VoiceCommand.swift',
    'mac/Sources/LaughCounter/Store.swift',
    'mac/Sources/LaughCounter/LaughDetector.swift',
  ));
  assert.deepEqual(findings, []);
});

test('on-device-speech fires on a request that never opts out', () => {
  const findings = onDeviceSpeech.run(ctxOf({
    'mac/Sources/LaughCounter/VoiceCommand.swift':
      'let newRequest = SFSpeechAudioBufferRecognitionRequest()\n'
      + 'newRequest.shouldReportPartialResults = true\n',
  }));
  assert.equal(findings.length, 1);
  assert.equal(findings[0].line, 1);
});

test('on-device-speech stays quiet on the real VoiceCommand', () => {
  const findings = onDeviceSpeech.run(realCtx('mac/Sources/LaughCounter/VoiceCommand.swift'));
  assert.deepEqual(findings, []);
});

test('no-audio-persistence fires on an audio-writing API in the capture path', () => {
  const findings = noAudioPersistence.run(ctxOf({
    'mac/Sources/LaughCounter/ClipWriter.swift':
      'let file = try AVAudioFile(forWriting: url, settings: format.settings)\n'
      + 'let recorder = try AVAudioRecorder(url: url, settings: settings)\n',
  }));
  assert.equal(findings.length, 2);
  assert.deepEqual(findings.map((f) => f.line), [1, 2]);
  assert.match(findings[0].what, /AVAudioFile/);
  assert.match(findings[1].what, /AVAudioRecorder/);
});

test('no-audio-persistence stays quiet on a read-only AVAudioFile load (a bundled sound asset)', () => {
  const findings = noAudioPersistence.run(ctxOf({
    'mac/Sources/LaughCounter/CustomChime.swift':
      'let file = try AVAudioFile(forReading: bundledSoundURL)\n',
  }));
  assert.deepEqual(findings, []);
});

test('no-audio-persistence stays quiet on the real capture path', () => {
  const findings = noAudioPersistence.run(realCtx(
    'mac/Sources/LaughCounter/AudioHub.swift',
    'mac/Sources/LaughCounter/VoiceCommand.swift',
    'mac/Sources/LaughCounter/Store.swift',
    'mac/Sources/LaughCounter/LaughDetector.swift',
    'mac/Sources/LaughCounter/AppLog.swift',
  ));
  assert.deepEqual(findings, []);
});

test('single-storage-directory fires on a second storage root', () => {
  const findings = singleStorageDirectory.run(ctxOf({
    'mac/Sources/LaughCounter/ModelCache.swift':
      'let base = FileManager.default.urls(for: .cachesDirectory,\n'
      + '                                   in: .userDomainMask)[0]\n',
    'mac/Sources/LaughCounter/Export.swift':
      'let dirs = NSSearchPathForDirectoriesInDomains(.documentDirectory, .userDomainMask, true)\n',
  }));
  assert.equal(findings.length, 2);
  assert.deepEqual(findings.map((f) => f.line), [1, 1]);
  assert.match(findings[0].what, /cachesDirectory/);
  assert.match(findings[1].what, /documentDirectory/);
});

test('single-storage-directory sees a call split across lines', () => {
  const findings = singleStorageDirectory.run(ctxOf({
    'mac/Sources/LaughCounter/Scratch.swift':
      '// two blank-ish lines first\n'
      + 'let base = FileManager.default.urls(\n'
      + '    for: .downloadsDirectory,\n'
      + '    in: .userDomainMask)[0]\n',
  }));
  assert.equal(findings.length, 1);
  assert.equal(findings[0].line, 2);
});

test('single-storage-directory accepts the fully-qualified allowed case', () => {
  const findings = singleStorageDirectory.run(ctxOf({
    'mac/Sources/LaughCounter/Store.swift':
      'let base = FileManager.default.urls(for: FileManager.SearchPathDirectory.applicationSupportDirectory,\n'
      + '                                    in: .userDomainMask)[0]\n',
  }));
  assert.deepEqual(findings, []);
});

test('no-listener fires on every shape of inbound listener', () => {
  const findings = noListener.run(ctxOf({
    'mac/Sources/LaughCounter/Dashboard.swift':
      'import Vapor\n'
      + 'let listener = try NWListener(using: .tcp, on: 8080)\n'
      + 'let fd = socket(AF_INET, SOCK_STREAM, 0)\n',
    'mac/Sources/LaughCounter/Agent.swift':
      'let xpc = NSXPCListener(machServiceName: "com.laughcounter.agent")\n'
      + 'let port = SocketPort(tcpPort: 9000)\n'
      + 'let s = CFSocketCreate(nil, AF_INET, SOCK_STREAM, 0, 0, nil, nil)\n',
  }));
  assert.equal(findings.length, 6);
  assert.deepEqual(findings.map((f) => f.line), [1, 2, 3, 1, 2, 3]);
  assert.match(findings[0].what, /HTTP server framework/);
  assert.match(findings[1].what, /NWListener/);
  assert.match(findings[2].what, /socket\(2\)/);
  assert.match(findings[3].what, /NSXPCListener/);
  assert.match(findings[4].what, /SocketPort/);
  assert.match(findings[5].what, /CFSocket/);
});

// The false alarm the check is built to avoid: this app's whole vocabulary is
// "listening" (at the microphone), which must never read as a socket.
test("no-listener stays quiet on the mic's listening vocabulary", () => {
  const findings = noListener.run(ctxOf({
    'mac/Sources/LaughCounter/AppDelegate.swift':
      'private var listening = false\n'
      + 'private func requestListening() {\n'
      + '    self.finishListening()\n'
      + '    hub.stopListening()\n'
      + '}\n'
      + '// The menu must stop claiming to listen while nothing is arriving.\n'
      + 'let key = "keepMacAwakeWhileListening"\n',
  }));
  assert.deepEqual(findings, []);
});

test('no-listener stays quiet on the real sources', () => {
  const findings = noListener.run(realCtx(
    'mac/Sources/LaughCounter/AppDelegate.swift',
    'mac/Sources/LaughCounter/AudioHub.swift',
    'mac/Sources/LaughCounter/AudioDiagnostics.swift',
    'mac/Sources/LaughCounter/VoiceCommand.swift',
    'mac/Sources/LaughCounter/Store.swift',
    'mac/Sources/LaughCounter/AppLog.swift',
    'mac/Sources/LaughCounter/LaughDetector.swift',
    'mac/Sources/LaughCounter/LaughCounter.swift',
    'mac/Sources/LaughCounter/Chime.swift',
    'mac/Sources/LaughCounter/main.swift',
  ));
  assert.deepEqual(findings, []);
});

test('single-storage-directory stays quiet on the real sources', () => {
  const findings = singleStorageDirectory.run(realCtx(
    'mac/Sources/LaughCounter/AppLog.swift',
    'mac/Sources/LaughCounter/Store.swift',
    'mac/Sources/LaughCounter/AudioHub.swift',
    'mac/Sources/LaughCounter/VoiceCommand.swift',
    'mac/Sources/LaughCounter/LaughDetector.swift',
    'mac/Sources/LaughCounter/AppDelegate.swift',
    'mac/Sources/LaughCounter/Chime.swift',
    'mac/Sources/LaughCounter/LaughCounter.swift',
    'mac/Sources/LaughCounter/main.swift',
  ));
  assert.deepEqual(findings, []);
});

#!/usr/bin/env node
// World-scope conformance runner (see DESIGN.md): the rules that audit repo
// state as it exists now, plus the pack-agnostic settings/load integrity
// diagnostics (malformed config, an unknown pack, a broken pack.mjs). Rules that
// judge the current change (`scope: 'work'`) run in check_the_work.mjs, which
// this file shares no code with — only the scope-blind mechanism helpers
// (run-active-pack-rules.mjs, report-findings.mjs). It names NO pack: adoption
// interview hygiene is a skill-owned check that rides its own pack's activation,
// and a malformed `questions` field is a load fault the pack registry reports.
// Wired into the project's test/CI flow, not the Stop hook. Dependency-free Node ≥18.
//   (default)   whole-repo sweep — milliseconds on a text corpus, sees cross-file breakage
//   --changed   transitional: scope to files changed vs the merge-base with main
//               (adopting a repo with a backlog only — not the enforcement default)
//   --base REF  override the base ref
//   --list      machine-readable catalog of every rule, both scopes (id, severity, description, doc)
//   --init      write .claudinite-checks.json — basics plus the fingerprinted packs
import { writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { buildContext } from './helpers/repo-context.mjs';
import { discoverPacks, resolveDeclaredPacks } from '../pack_loader/pack-registry.mjs';
import { runActivePackRules, packRules } from './run-active-pack-rules.mjs';
import { reportFindings } from './report-findings.mjs';

const configError = (what, fix) => ({
  rule: 'config', severity: 'blocking', file: '.claudinite-checks.json', line: null,
  what, why: 'the settings file is what executes — a bad key, value, or pack name silently changes what runs', fix, doc: 'engine/checks/README.md',
});

const args = process.argv.slice(2);
const has = (flag) => args.includes(flag);
const value = (flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
const root = value('--root') || process.cwd();

if (has('--list')) {
  const { packs } = await discoverPacks({ localRoot: root });
  for (const r of packRules(packs)) {
    console.log(`${r.id}\t${r.severity}\t${r.description}\t${r.doc}`);
  }
  process.exit(0);
}

if (has('--init')) {
  const path = join(root, '.claudinite-checks.json');
  if (existsSync(path)) {
    console.log(`${path} already exists — leaving it as-is.`);
    process.exit(0);
  }
  const { packs } = await discoverPacks({ localRoot: root });
  const ctx = buildContext({ root, mode: 'all' });
  // No pack is active by default, so the baseline is seeded as an explicit
  // declaration alongside the fingerprinted packs: every pack that flags
  // `seededByDefault` is written in (discovered structurally — the engine names
  // no pack), plus the ones a fingerprint detects. A seeded pack is still
  // opt-out-able where its own policy allows (baselining re-adds only the packs
  // whose absence it treats as drift), so removing a seeded declaration can
  // stick; each seeded pack ships its own one-time seed migration for the fleet.
  // Local packs are declared by hand, never fingerprinted or seeded — exclude
  // them from --init's seeding so a repo that already carries local packs (but
  // no config yet) doesn't auto-declare them.
  const seeded = packs.filter((p) => p.seededByDefault && !p.local).map((p) => p.id);
  const detected = [...seeded, ...packs.filter((p) => p.detect && !p.local && p.detect(ctx)).map((p) => p.id)];
  // A pack can't be imported without its dependencies — pull each declared pack's
  // `requires` closure into the declaration so it's complete and visible.
  const declared = resolveDeclaredPacks(detected, packs);
  // maintenance.delivery is deliberately materialized, not defaulted — the selection
  // must be visible in the file where a project would change it (see engine/checks/README.md).
  // Only what carries a decision: the declaration and the always-explicit
  // delivery. Empty rules/accept boilerplate is noise, not settings (#385);
  // loadConfig defaults absent keys.
  writeFileSync(path, `${JSON.stringify({ packs: declared, maintenance: { delivery: 'auto-merge' } }, null, 2)}\n`);
  console.log(`Wrote ${path} (packs: ${declared.join(', ')}).`);
  // The adoption interview (surfacing each declared pack's pending questions) is
  // driven by the adopt-claudinite skill / bootstrap.md, and nudged every session
  // by the SessionStart interview-check step — not printed here, so this runner
  // imports no pack.
  process.exit(0);
}

const { packs, errors: packErrors } = await discoverPacks({ localRoot: root });
const ctx = buildContext({ root, mode: has('--changed') ? 'changed' : 'all', baseOverride: value('--base') });

// Settings/load integrity — pack-agnostic, so the world runner owns them.
// Settings validity is checked at load: malformed JSON, an unknown
// property, and a wrong pack name are all equally settings errors. loadConfig
// reports the first two; the runner adds unknown pack names (only it holds the
// registry) and broken/duplicate local pack.mjs faults.
const findings = [];
for (const e of ctx.config.errors) findings.push(configError(e.what, e.fix));
for (const e of packErrors) findings.push(configError(e.what, e.fix));
// knownIds spans canon AND local packs, so a declared local pack id is valid and
// the unknown-pack message lists it among the declarable packs. ctx.config.packs
// is loadConfig's normalized view — bare ids, a namespaced local_packs/<name>
// declaration already resolved through packEntryId.
const knownIds = new Set(packs.map((p) => p.id));
for (const name of ctx.config.packs) {
  if (typeof name === 'string' && !knownIds.has(name)) {
    findings.push(configError(`declares unknown pack "${name}"`, `remove it or fix the name — declarable packs: ${[...knownIds].sort().join(', ')}`));
  }
}
// (Adoption-interview hygiene is a skill-owned check that runs below with the
// other active-pack rules; a malformed `questions` field arrives as a load fault
// in packErrors above. Neither names a pack here.)

// The world rules: everything not scoped to the work. A broken contributedRules
// seam is a config-level fault surfaced here (the world runner owns diagnostics).
findings.push(...runActivePackRules(ctx, packs, {
  includeRule: (rule) => rule.scope !== 'work',
  onContributeError: (pack, e) => findings.push(configError(
    `the "${pack.id}" pack's contributedRules failed: ${e.message}`, 'fix the pack manifest, or the contribution it interprets')),
}));

const blocking = reportFindings(findings, ctx.config, { scopeLabel: 'world', mode: ctx.mode, baseRef: ctx.baseRef });
process.exit(blocking ? 1 : 0);

import { spawnSync } from 'node:child_process';
import { readFileSync, existsSync, statSync } from 'node:fs';
import { join, resolve, sep } from 'node:path';
import { parseEntries } from './session-transcript.mjs';
import { SHARED_SUBDIR, packEntryId } from '../../pack_loader/pack-registry.mjs';

function sh(root, cmd, args, { allowFail = false, input = undefined, timeout = undefined } = {}) {
  const r = spawnSync(cmd, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, input, timeout });
  if (r.status !== 0 && !allowFail) {
    throw new Error(`${cmd} ${args.join(' ')} failed (${r.status}): ${r.stderr}`);
  }
  return r.status === 0 ? r.stdout : null;
}

const git = (root, ...args) => sh(root, 'git', args);
const gitTry = (root, ...args) => sh(root, 'git', args, { allowFail: true });

function resolveBaseRef(root) {
  for (const ref of ['origin/main', 'origin/master', 'main', 'master']) {
    if (gitTry(root, 'rev-parse', '--verify', '--quiet', `${ref}^{commit}`) !== null) return ref;
  }
  return null;
}

const FETCH_TIMEOUT_MS = 8000;

// A remote-tracking base ref is only as fresh as the last fetch, and a cloud session's
// clone freezes it at container-creation time — so every commit the base branch gained
// since lands inside `mergeBase..HEAD` and gets billed to the work. That is a wrong
// verdict, not a stale one: the delta rules (squash-merge-history above all, a *blocking*
// rule) report other people's commits as introduced by this change, and `--changed`
// widens to files the change never touched. Refreshing the ref once per run is what makes
// "the work" mean the work.
//
// Best-effort by construction — no network, no remote, a lock held, a slow server: the
// fetch fails or times out and the run continues against the ref as it stands, exactly as
// before this existed. It writes ONLY the remote-tracking ref (explicit refspec, no tags):
// no local branch, no index, no working tree, nothing the session could be surprised by.
// Set CLAUDINITE_CHECKS_NO_FETCH=1 to skip it (sealed sandboxes, or to pin a base).
function refreshBaseRef(root, ref) {
  if (!ref || process.env.CLAUDINITE_CHECKS_NO_FETCH === '1') return;
  const m = /^([^/]+)\/(.+)$/.exec(ref);
  if (!m) return; // a local branch is already as current as the checkout — nothing to fetch
  const [, remote, branch] = m;
  sh(root, 'git', ['fetch', '--quiet', '--no-tags', remote,
